    project(lng: number, lat: number): ProjectedPoint {
        const {scale, cosPhi} = this;
        const x = degToRad(lng) * cosPhi;
        const y = Math.sin(degToRad(lat)) / cosPhi;

        return {
            x: (x * scale) + 0.5,
            y: (-y * scale) + 0.5,
            z: 0
